plugins {
    alias(libs.plugins.kotlin.multiplatform)
    id("dev.knshell.icons.pack")
}

kotlin {
    linuxX64()
    sourceSets {
        nativeMain.dependencies {
            // api: pack consumers compose Icon(...) + IconStyle from :icons:core.
            api(project(":icons:core"))
        }
    }
}

// The whole pack is this block — the catalog and the SVG data are generated by
// icons-plugin (syncIcons + generateIcons). See docs/icons.md for adding a pack.
iconsPack {
    objectName.set("Lucide")
    packageName.set("dev.knshell.icons.lucide")
    npmPackage.set("lucide-static")
    version.set(libs.versions.lucideStatic.get())
    // npm tarballs keep the `package/` prefix; the plugin normalizes both spellings.
    iconsDir.set("icons")
    tintAttribute.set("stroke")
    defaultStrokeWidth.set(2.0)
    defaultViewBoxSize.set(24.0)
}
